const grouped = {};

// Step 1: Group by item
for (const item of items) {
  const key = item.json.item;

  if (!grouped[key]) {
    grouped[key] = [];
  }

  grouped[key].push(item.json);
}

// Step 2: Process each group
const result = [];

for (const key in grouped) {
  const records = grouped[key];

  // Sort by date (latest first)
  records.sort((a, b) => new Date(b.last_purchase_date) - new Date(a.last_purchase_date));

  const latest = records[0];
  const historical = records.slice(1);

  result.push({
    json: {
      item: key,
      latest,
      historical
    }
  });
}

return result;

return items.map(item => {
  const latest = item.json.latest;
  const historical = item.json.historical;

  let totalValue = 0;
  let totalQty = 0;

  // Calculate weighted average
  for (const record of historical) {
    totalValue += record.price_internal * record.quantity;
    totalQty += record.quantity;
  }

  const avg_market_price = totalQty > 0 ? totalValue / totalQty : latest.price_internal;

  // Variance
  const variance = latest.price_internal - avg_market_price;
  const variance_pct = (variance / avg_market_price) * 100;

  // Basic trend (simple logic for now)
  let trend = "stable";
  if (historical.length > 0) {
    const lastHistorical = historical[0].price_internal;
    if (latest.price_internal > lastHistorical) trend = "rising";
    else if (latest.price_internal < lastHistorical) trend = "falling";
  }

  return {
    json: {
      item: item.json.item,
      category: latest.category,
      supplier: latest.supplier,
      price_internal: latest.price_internal,
      quantity: latest.quantity,
      avg_market_price: parseFloat(avg_market_price.toFixed(2)),
      variance: parseFloat(variance.toFixed(2)),
      variance_pct: parseFloat(variance_pct.toFixed(2)),
      trend,
      contract_type: latest.contract_type,
      region: latest.region,
      target_price_last: latest.target_price_last,
      price_vs_target_pct : ((latest.price_internal - latest.target_price_last) / latest.target_price_last) * 100
    }
  };
});

const itemName = $('Process Items for Market News').first().json.item;

// Take only top 5 news for THIS item
const topArticles = items.slice(0, 5);

const headlines = topArticles.map(a => 
  (a.json.title || "").toLowerCase()
);

const combined = headlines.join(" ");

let market_trend = "stable";

if (/rise|rising|increase|surge|jump|higher/.test(combined)) {
  market_trend = "rising";
} else if (/fall|falling|drop|decline|lower|decrease/.test(combined)) {
  market_trend = "falling";
} else if (/volatile|uncertain|fluctuat/.test(combined)) {
  market_trend = "volatile";
}

return [{
  json: {
    item: itemName,
    market_trend,
    headlines,
    news_summary: headlines.join(" | ")
  }
}];

