return items.map((item, index) => {
  let content = item.json.output || "";

  // Clean markdown
  content = content.replace(/```json|```/g, '').trim();

  let parsed = {};

  try {
    parsed = JSON.parse(content);
  } catch (e) {
    parsed = {
      risk_level: "unknown",
      ai_summary: content
    };
  }


  const original = $items("Merge Pricing Data with Market Signals")[index].json;

  return {
    json: {
            item: original.item,
      category: original.category,
      supplier: original.supplier,
      price_internal: original.price_internal,
      avg_market_price: original.avg_market_price,
      variance_pct: original.variance_pct,
      market_trend: original.market_trend,


      ...parsed
    }
  };
});

